# shellcheck shell=bash disable=SC2034
# Sourced by run.sh, which reads CHANNEL, START, CREATE_FLAGS and POOL_FLAGS and calls plant, before, break_it and after.
# 1: a budget that forbids the eviction; the pool upgrade uses GKE's default surge, so the stall is isolated from capacity
CHANNEL=REGULAR; START=1.34; POOL_FLAGS="--num-nodes 1 --machine-type e2-standard-2"
plant(){ pause_deploy pinned 1; K -n scen create pdb pinned --selector=app=pinned --max-unavailable=0 --dry-run=client -o yaml | K -n scen apply -f - >/dev/null; }
before(){ ev budget before K -n scen get pdb pinned -o custom-columns='NAME:.metadata.name,MAXU:.spec.maxUnavailable,ALLOWED:.status.disruptionsAllowed,HEALTHY:.status.currentHealthy'; POD=$(K -n scen get pod -l app=pinned -o jsonpath='{.items[0].metadata.name}'); ev budget eviction-by-hand K create --raw "/api/v1/namespaces/scen/pods/$POD/eviction" -f /dev/stdin <<<"{\"apiVersion\":\"policy/v1\",\"kind\":\"Eviction\",\"metadata\":{\"name\":\"$POD\",\"namespace\":\"scen\"}}"; }
break_it(){ V=$(newest_patch REGULAR 1.35); upgrade_master "$V"; upgrade_pool work-pool "$V" budget:scen:app=pinned; }
after(){ ev budget after-pods K -n scen get pods -l app=pinned -o wide; ev budget after-events K -n scen get events --sort-by=.lastTimestamp -o custom-columns='T:.lastTimestamp,R:.reason,O:.involvedObject.name,M:.message'; ev budget op-timeline G container operations list --zone "$ZONE" --filter="targetLink~clusters/$CLUSTER/nodePools" --format='table(operationType,status,startTime,endTime)'; ev budget refused-evictions-audit G logging read "resource.type=k8s_cluster AND resource.labels.cluster_name=$CLUSTER AND protoPayload.methodName=io.k8s.core.v1.pods.eviction.create AND protoPayload.response.code=429" --freshness 3h --limit 3 --format='value(timestamp,protoPayload.authenticationInfo.principalEmail)'; }
